-- Building code jurisdiction directory
--
-- Reference data for SPEC_ARCHITECTURAL_RESOURCE_CENTER.md's "Building code
-- references" content category. This is deliberately its own table, not an
-- extension of bid_sources (010_bid_monitor.sql) -- bid_sources tracks
-- procurement/bid-opportunity portals for the Bid Monitor tool, a different
-- purpose from tracking which government body has adopted (or not adopted)
-- a building code and where to find it.
--
-- Texas is the first state populated (see seed data at the end of this
-- file). Schema is state-agnostic on purpose: `state` is a plain USPS code
-- column, and `status` covers the three real-world outcomes research turns
-- up in any state -- a verified adoption-authority link, a confirmed
-- absence of an adopted code, or a genuinely unresolved case -- rather than
-- assuming every state's county/city authority split mirrors Texas's
-- permissive-county model (Local Government Code Title 7, Chapter 233).
-- Adding a new state is a data addition (INSERT rows), not a schema change.

CREATE TABLE building_code_jurisdictions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

  state TEXT NOT NULL, -- USPS 2-letter code, e.g. 'TX'
  jurisdiction_type TEXT NOT NULL CHECK (jurisdiction_type IN ('county', 'city')),
  name TEXT NOT NULL, -- e.g. 'Tarrant', 'Fort Worth' (no "County"/"City of" prefix)
  county_name TEXT, -- for jurisdiction_type = 'city': the county/counties it sits in, free text

  population INTEGER,
  population_basis TEXT, -- e.g. '2020 Census', '2024 estimate'

  status TEXT NOT NULL CHECK (status IN ('verified_link', 'no_code_adopted', 'unresolved')),
  url TEXT, -- adoption-authority page (verified_link) or general homepage (no_code_adopted); NULL when unresolved
  url_verified_at TIMESTAMPTZ, -- when the URL was last confirmed to resolve (2xx/3xx)
  url_http_verified BOOLEAN NOT NULL DEFAULT false,

  notes TEXT, -- research finding, one or two sentences
  unresolved_reason TEXT, -- populated only when status = 'unresolved'

  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  UNIQUE (state, jurisdiction_type, name)
);

CREATE INDEX idx_building_code_jurisdictions_state ON building_code_jurisdictions(state);
CREATE INDEX idx_building_code_jurisdictions_type ON building_code_jurisdictions(jurisdiction_type);
CREATE INDEX idx_building_code_jurisdictions_status ON building_code_jurisdictions(status);

ALTER TABLE building_code_jurisdictions ENABLE ROW LEVEL SECURITY;

-- Admin-only for this first pass, matching bid_sources' precedent (010_bid_monitor.sql).
-- This is reference content ultimately meant for the Architect Portal's resource
-- center (SPEC_ARCHITECTURAL_RESOURCE_CENTER.md), but that read surface isn't
-- built yet -- widen with a SELECT policy for authenticated/architect roles when it is.
CREATE POLICY building_code_jurisdictions_admin_all ON building_code_jurisdictions
  FOR ALL
  USING (auth.jwt() ->> 'role' = 'admin')
  WITH CHECK (auth.jwt() ->> 'role' = 'admin');

COMMENT ON TABLE building_code_jurisdictions IS
  'Building-code adoption authority per jurisdiction (county/city), by state. First populated for Texas -- see SPEC_ARCHITECTURAL_RESOURCE_CENTER.md "Building code references".';

-- Seed data: Texas counties (254) and incorporated cities >=10,000 population (226).
-- Researched 2026-08-27 via individual per-jurisdiction web research and per-URL HTTP verification.
-- See STATE_OF_THE_BUILD.md / SESSION_STATE.md (afs-fl-024) for the full methodology and breakdown.
;
